: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(67 128 180 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgba(0, 0, 0, 0.075); font-weight: bolder;">Oui, absolument.</span></p><p node="[object Object]" class="" style="--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(67 128 180 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgba(0, 0, 0, 0.075);">La base de données et l\'administration sont conçues pour être évolutives. Une fois la base connectée, nous pourrons ajouter de nouveaux champs, corriger des options et enrichir le tableau de bord d\'administration à tout moment selon vos besoins au fur et à mesure que vous les visualisez.</p></div></div></div></div></div></div></div></div></div>', 'La base de données devait être implémentée à la Phase 1 de la feuille de route Back-End (task-backend.md).Pourquoi elle n\'est pas encore en place : Jusqu\'ici, l', 'La base de données devait être implémentée à la Phase 1 de la feuille de route Back-End (task-backend.md).Pourquoi elle n\'est pas encore en place : Jusqu\'ici, l', 'text', '/assets/core/uploads/1784804852443_merci.png', '/assets/core/uploads/1784804852443_merci.png', '[{"url":"/assets/core/uploads/1784804865251_Use_the_uploaded_AUTO-ÉCOLE_PILOTE_202606170923.jpeg","caption":"a l\'ecole "},{"url":"/assets/core/uploads/1784804865357_Use_the_uploaded_AUTO-ÉCOLE_PILOTE_202606170919.jpeg","caption":"la route a prendr "},{"url":"/assets/core/uploads/1784804865453_Use_the_uploaded_AUTO-ÉCOLE_PILOTE_202606170912.jpeg","caption":"autoeco"},{"url":"/assets/core/uploads/1784804865524_Use_the_uploaded_AUTO-ÉCOLE_PILOTE_202606170856.jpeg","caption":""}]', '', '', 'Draft', 0, 'STANDARD_FEED', '', 'À l\'instant', '2026-08-31 10:17:22', '2026-08-31 10:17:22');
INSERT INTO `articles` (`id`, `slug`, `title`, `author`, `category`, `rubrique`, `subcategory`, `badge`, `content`, `summary`, `desc`, `format`, `cover_image`, `image`, `article_gallery`, `video_url`, `audio_file`, `status`, `is_vip_only`, `placement_target`, `meta`, `updated`, `created_at`, `updated_at`) VALUES ('art-1784804290526', NULL, 'L’Aube de la Souveraineté Quantique', 'Elena Moretti', 'magazine-01-intelligence', 'The Brief', 'The Brief', 'ARTICLE', 'Contenu détaillé de l’article quantique...', 'Une exploration exclusive sur les disruptions majeures du calcul quantique dans l’économie de 2026.', 'Une exploration exclusive sur les disruptions majeures du calcul quantique dans l’économie de 2026.', 'text', '/assets/core/img/mag_hero_03.png', '/assets/core/img/mag_hero_03.png', '[]', '', '', 'Draft', 0, 'HERO_MAIN', '', 'À l\'instant', '2026-08-31 10:17:22', '2026-08-31 10:17:22');
INSERT INTO `articles` (`id`, `slug`, `title`, `author`, `category`, `rubrique`, `subcategory`, `badge`, `content`, `summary`, `desc`, `format`, `cover_image`, `image`, `article_gallery`, `video_url`, `audio_file`, `status`, `is_vip_only`, `placement_target`, `meta`, `updated`, `created_at`, `updated_at`) VALUES ('hero-main-01', NULL, 'La Métamorphose du Pouvoir à l\'Ère des Algorithmes', 'Elena Moretti', 'Stratégie', 'The Brief', 'The Brief', 'ARTICLE', '<p>Une analyse prospective sur la manière dont les modèles d\'intelligence synthétique redéfinissent la diplomatie et les réseaux d\'influence globale.</p>', 'Une analyse prospective sur la manière dont les modèles d\'intelligence synthétique redéfinissent la diplomatie et les réseaux d\'influence globale.', 'Une analyse prospective sur la manière dont les modèles d\'intelligence synthétique redéfinissent la diplomatie et les réseaux d\'influence globale.', 'text', '/assets/core/img/mag_hero_03.png', '/assets/core/img/mag_hero_03.png', '[]', '', '', 'Published', 0, 'HERO_MAIN', '', 'Il y a 2 heures', '2026-08-31 10:17:22', '2026-08-31 10:17:22');
