INSERT INTO `articles` (`id`, `slug`, `title`, `author`, `category`, `rubrique`, `subcategory`, `badge`, `content`, `summary`, `desc`, `format`, `cover_image`, `image`, `article_gallery`, `video_url`, `audio_file`, `status`, `is_vip_only`, `placement_target`, `meta`, `updated`, `created_at`, `updated_at`) VALUES ('hero-side-02', NULL, 'Biotechnologie & Transhumanisme : Les Frontières Éthiques', 'Dr. Sarah Chen', 'Futurisme', 'The Brief', 'The Brief', 'ARTICLE', '<p>Enquête sur les laboratoires secrets et les régulations émergentes autour de l\'édition génomique humaine.</p>', 'Enquête sur les laboratoires secrets et les régulations émergentes autour de l\'édition génomique humaine.', 'Enquête sur les laboratoires secrets et les régulations émergentes autour de l\'édition génomique humaine.', 'text', '/assets/core/img/mag_hero_05.png', '/assets/core/img/mag_hero_05.png', '[]', '', '', 'Published', 1, 'HERO_SIDE', '', 'Hier', '2026-08-31 10:17:22', '2026-08-31 10:17:22');
