INSERT INTO `articles` (`id`, `slug`, `title`, `author`, `category`, `rubrique`, `subcategory`, `badge`, `content`, `summary`, `desc`, `format`, `cover_image`, `image`, `article_gallery`, `video_url`, `audio_file`, `status`, `is_vip_only`, `placement_target`, `meta`, `updated`, `created_at`, `updated_at`) VALUES ('pensee-systemique', NULL, 'Le retour de la pensée systémique dans la stratégie d\'entreprise', 'Elena Rousseau', 'magazine-01-intelligence', 'The Brief', 'The Brief', 'ARTICLE', '<p>Comment les approches holistiques transforment la prise de décision face à des crises interconnectées.</p>', 'Comment les approches holistiques transforment la prise de décision face à des crises interconnectées.', 'Comment les approches holistiques transforment la prise de décision face à des crises interconnectées.', 'text', '/assets/core/img/mag_hero_04.png', '/assets/core/img/mag_hero_04.png', '[]', '', '', 'Published', 0, 'MAGAZINE_FEED', '', '8 min de lecture', '2026-08-31 10:17:22', '2026-08-31 10:17:22');
