INSERT INTO `dossiers` (`id`, `title`, `coordinator`, `description`, `summary`, `cover_image`, `articles`, `is_vip_only`, `is_featured`, `category`, `magazine`, `label`, `status`, `created_at`, `updated_at`) VALUES ('dos-04', 'Longevity & Santé Préventive : Repousser les Limites du Vivant', 'Dr. Antoine Moreau', 'Innovations biomédicales, protocoles de longévité cellulaire et médecine régénérative de pointe.', 'L\'impact des thérapies géniques et de la nutrition avancée sur l\'espérance de vie en bonne santé.', '/assets/core/img/vault-2.png', '[]', 0, 0, 'Sciences & Bien-Être', 'magazine-09-longevity', 'DOSSIER RECHERCHE', 'Published', '2026-08-31 14:52:50', '2026-08-31 14:52:50');
